/* Locally bundled fonts keep the portfolio self-contained. */
@font-face{font-family:"Inter";src:url("data:font/ttf;base64,") format("truetype");font-style:normal;font-weight:100 900;font-display:swap}
@font-face{font-family:"Source Serif 4";src:url("data:font/ttf;base64,") format("truetype");font-style:normal;font-weight:200 900;font-display:swap}
@font-face{font-family:"Source Serif 4";src:url("data:font/ttf;base64,") format("truetype");font-style:italic;font-weight:200 900;font-display:swap}
:root{
  --bg:#F7F5F0;
  --card:#FFFEFB;
  --ink:#14233B;
  --body:#3A4A5E;
  --muted:#3A4A5E;
  --line:#DDDCD5;
  --terra:#2F5D8C;
  --terra-dark:#2F5D8C;
  --peach:#DFE8EE;
  --sage:#E7EBE7;
  --mustard:#EAE2D3;
  --r:20px;
  --shadow:0 8px 24px rgba(32,52,72,.07);
  --font:"Inter","Segoe UI",system-ui,-apple-system,sans-serif;
  --serif:"Source Serif 4",Georgia,"Times New Roman",serif;
  --mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--body);font-family:var(--font);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
a{color:var(--terra)}
h1,h2,h3{color:var(--ink);font-family:var(--serif);line-height:1.15;margin:0 0 .5em;letter-spacing:-.01em}
h1{font-size:clamp(2.2rem,5.2vw,3.7rem);font-weight:700}
h2{font-size:clamp(1.5rem,2.7vw,2rem);font-weight:700}
h3{font-size:1.2rem;font-weight:700}
p{margin:0 0 1em}
.small{font-size:.92rem;color:var(--muted)}
.skip{position:absolute;left:-999px;top:8px;background:var(--ink);color:#fff;padding:8px 14px;border-radius:10px;z-index:50}
.skip:focus{left:8px}
:focus-visible{outline:3px solid var(--terra);outline-offset:3px}

.top{position:sticky;top:0;z-index:20;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px clamp(16px,4vw,48px);background:rgba(247,245,240,.97);border-bottom:1.5px solid var(--line)}
.logo{color:var(--ink);display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:700}
.logo-badge{display:grid;place-items:center;width:38px;height:38px;background:var(--terra);color:#fff;border-radius:50%;font-weight:800;font-size:.9rem}
.logo-text{font-family:var(--serif);font-size:1.15rem}
.tabs{display:flex;gap:4px;flex-wrap:wrap}
.tabs a{color:var(--ink);text-decoration:none;font-weight:600;padding:8px 16px;border-radius:999px;transition:background .15s,color .15s}
.tabs a:hover{background:var(--peach)}
.tabs a[aria-current="page"]{background:var(--terra);color:#fff}

main{max-width:1100px;margin:0 auto;padding:clamp(24px,5vw,56px) clamp(16px,4vw,32px) 40px}
.js .page{display:none}
.js .page.active{display:block;animation:rise .4s ease}
@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}

.sticker{display:inline-block;font-weight:700;font-size:.85rem;padding:6px 16px;border-radius:999px;background:var(--peach);color:var(--terra-dark);margin-bottom:18px}
.s-yellow{background:var(--mustard);color:#65563D}
.s-coral{background:var(--peach);color:var(--terra-dark)}
.s-teal{background:var(--sage);color:#46564C}
.s-purple{background:#E7E8EF;color:#36475D}
.hl{color:var(--terra);font-style:italic}
.lead{font-size:1.2rem;max-width:62ch;color:var(--body)}

.btn{display:inline-block;font-weight:700;text-decoration:none;padding:13px 26px;border-radius:999px;transition:transform .15s,box-shadow .15s,background .15s}
.btn:hover{transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-dark{background:var(--terra);color:#fff}
.btn-dark:hover{background:var(--terra-dark)}
.btn-line{color:var(--ink);background:transparent;border:2px solid var(--ink)}
.cta-row{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}

.chips{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.chips li{font-weight:600;font-size:.88rem;padding:6px 14px;border-radius:999px;background:var(--card);border:1.5px solid var(--line)}
.chips.big li{font-size:1rem;padding:10px 18px;background:var(--sage);border-color:transparent}

.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:center}
.portrait-wrap{position:relative;max-width:360px;justify-self:center;width:100%}
.portrait{position:relative;aspect-ratio:4/5;border-radius:200px 200px 28px 28px;background:var(--peach);display:grid;place-items:center;overflow:hidden;box-shadow:0 4px 14px rgba(47,93,140,.15)}
.portrait::before{content:"NK";font-family:var(--serif);font-size:5rem;font-weight:700;color:var(--terra)}
.portrait::after{content:"";position:absolute;inset:0;background:url("data:image/jpeg;base64,") center/cover no-repeat}
.note{position:absolute;font-weight:700;font-size:.85rem;padding:7px 14px;border-radius:999px;background:var(--card);box-shadow:var(--shadow)}
.n1{top:14%;left:-12%;transform:rotate(-4deg)}
.n2{bottom:26%;right:-8%;background:var(--mustard);transform:rotate(3deg)}
.n3{bottom:6%;left:-6%;background:var(--sage);transform:rotate(-2deg)}

.term{background:var(--ink);color:#F6EEE6;border-radius:var(--r);box-shadow:var(--shadow);overflow:hidden}
.term-bar{display:flex;align-items:center;gap:7px;padding:10px 16px;background:#4C3827;color:#CDB9A5;font-size:.82rem;font-weight:600}
.dot{width:11px;height:11px;border-radius:50%}
.d1{background:var(--terra)}.d2{background:var(--mustard)}.d3{background:var(--sage)}
.term-title{margin-left:8px}
.term-body{margin:0;padding:18px 20px;min-height:150px;font-family:var(--mono);font-size:.88rem;line-height:1.75;white-space:pre-wrap;word-break:break-word}
.term-body .c{color:var(--mustard)}
.term-body .ok{color:#B9D3A5}

.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:56px 0 8px}
.stat{padding:20px;border-radius:var(--r);display:flex;flex-direction:column;gap:4px}
.num{font-family:var(--serif);font-size:2.1rem;font-weight:700;line-height:1.2;margin-bottom:4px}
.lbl{font-weight:600;font-size:.9rem}
.c-yellow{background:var(--mustard)}.c-coral{background:var(--peach)}.c-teal{background:var(--sage)}.c-purple{background:#E7E8EF}

.sec{margin:56px 0 18px}
.cards{display:grid;gap:18px}
.cards.three{grid-template-columns:repeat(3,1fr)}
.cards.two{grid-template-columns:repeat(2,1fr)}
.card{background:var(--card);border:1.5px solid var(--line);border-radius:var(--r);padding:24px}
.card p:last-child{margin-bottom:0}
.card.c-yellow{background:var(--mustard);border-color:transparent}
.card.c-teal{background:var(--sage);border-color:transparent}
.card.c-coral{background:var(--peach);border-color:transparent}
.link-card{display:block;text-decoration:none;transition:transform .15s,box-shadow .15s}
.link-card:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.go{display:inline-block;margin-top:6px;font-weight:700}

.marquee{overflow:hidden;border-radius:var(--r);background:var(--sage);padding:16px 0}
.track{display:flex;gap:12px;width:max-content;animation:scroll 34s linear infinite;padding-left:12px}
.track span{color:#46564C;font-weight:700;padding:6px 18px;background:var(--card);border-radius:999px;white-space:nowrap}
.marquee:hover .track{animation-play-state:paused}
@keyframes scroll{to{transform:translateX(-50%)}}

.banner{margin-top:56px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;background:var(--peach);border-radius:var(--r);padding:32px}
.banner h2{margin:0 0 6px}.banner p{margin:0;max-width:52ch}

.split{display:grid;grid-template-columns:1.4fr .8fr;gap:32px;margin-top:20px;align-items:start}
.prose p{max-width:64ch}
.side dl{margin:0;display:grid;gap:2px}
.side dt{font-weight:700;font-size:.78rem;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-top:12px}
.side dd{margin:0;font-weight:600}

.timeline{list-style:none;padding:0;margin:0;display:grid;gap:14px}
.timeline small{font-weight:600;color:var(--muted)}
.timeline li{display:grid;grid-template-columns:150px 1fr;gap:18px;padding:20px;background:var(--card);border:1.5px solid var(--line);border-radius:var(--r)}
.timeline .when{font-weight:700;color:var(--terra-dark)}
.timeline p{margin:4px 0 0;color:var(--muted)}

.anatomy{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:28px 0 36px;font-weight:700}
.anatomy span{padding:8px 16px;border-radius:999px;background:var(--card);border:1.5px solid var(--line)}
.anatomy span.on{background:var(--terra);color:#fff;border-color:var(--terra)}
.anatomy i{font-style:normal;color:var(--muted)}

.wf{border-radius:var(--r);background:var(--card);border:1.5px solid var(--line);margin-bottom:28px;overflow:hidden;box-shadow:var(--shadow)}
.wf-head{display:flex;align-items:center;gap:16px;padding:18px 24px}
.wf-head h2{margin:0}
.wf-no{font-family:var(--serif);font-weight:700;background:var(--card);color:var(--terra-dark);padding:2px 12px;border-radius:999px;font-size:1.1rem}
.wf-body{padding:24px}
.wf-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px 32px}
.wf-grid h3{font-family:var(--font);font-size:.78rem;text-transform:uppercase;letter-spacing:.08em;color:var(--terra-dark);margin-bottom:4px}
.wf-grid p{margin:0}
details{margin-top:22px;border-top:1.5px dashed var(--line);padding-top:16px}
summary{cursor:pointer;font-weight:700;list-style:none;color:var(--terra-dark)}
summary::before{content:"+ ";font-family:var(--mono)}
details[open] summary::before{content:"\2212  "}
summary::-webkit-details-marker{display:none}
.sample{margin-top:12px;background:var(--bg);border-radius:14px;padding:18px}
.sample p{margin:0 0 .6em}
.tag{display:inline-block;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.07em;background:var(--sage);color:#46564C;padding:2px 10px;border-radius:999px;margin-top:6px!important}
.code{margin:0 0 .8em;padding:14px;background:var(--ink);color:#F6EEE6;border-radius:12px;font-family:var(--mono);font-size:.82rem;line-height:1.6;white-space:pre-wrap;word-break:break-word}

.ph{background:#FFE9A8;border-bottom:2px dotted var(--terra);padding:0 3px;border-radius:3px}
.foot-note{margin-top:32px}
.foot{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:24px clamp(16px,4vw,48px);border-top:1.5px solid var(--line);font-weight:600;font-size:.92rem;color:var(--muted)}

@media (max-width:860px){
  .hero,.split{grid-template-columns:1fr}
  .portrait-wrap{max-width:300px;order:-1}
  .n1{left:-4%}.n2{right:-2%}.n3{left:-2%}
  .stats{grid-template-columns:repeat(2,1fr)}
  .cards.three,.cards.two,.wf-grid{grid-template-columns:1fr}
  .timeline li{grid-template-columns:1fr;gap:4px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .track{animation:none}
  .js .page.active{animation:none}
}

.journey{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.journey .card{position:relative}
.journey .sticker{font-size:.78rem;margin-bottom:12px}
.journey h3{margin-bottom:.4em}
.journey p{font-size:.95rem;color:var(--muted)}
.journey li:not(:last-child)::after{content:"\2192";position:absolute;right:-16px;top:50%;transform:translateY(-50%);font-weight:700;color:var(--terra);background:var(--bg);width:14px;text-align:center;z-index:1}
@media (max-width:980px){.journey{grid-template-columns:repeat(2,1fr)}.journey li::after{display:none}}
@media (max-width:560px){.journey{grid-template-columns:1fr}}

.approach{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(2,1fr);gap:28px 36px}
.approach li{border-left:3px solid var(--terra);padding-left:20px}
.approach h3{margin-bottom:.35em}
.approach p{margin:0;color:var(--muted)}
@media (max-width:700px){.approach{grid-template-columns:1fr}}

.portrait{aspect-ratio:1/1;border-radius:28px}
.portrait::before{font-size:4rem}
.portrait-cap{margin:14px 0 0;text-align:center;font-size:.95rem;line-height:1.4;color:var(--muted)}
.portrait-cap strong{font-family:var(--serif);font-size:1.15rem;color:var(--ink)}
.note{display:none}

.portrait-wrap{max-width:200px}

.tools{display:flex;flex-wrap:wrap;gap:22px 46px;align-items:center;justify-content:center;background:var(--sage);border-radius:var(--r);padding:30px 24px}
.tool{display:inline-flex;align-items:center;min-height:32px;font-weight:800;font-size:1.05rem;color:var(--body)}
.tool-logo{height:30px;width:auto;max-width:150px;filter:grayscale(1);opacity:.7;transition:opacity .15s,filter .15s}
.tool:hover .tool-logo{filter:none;opacity:1}

.tools{gap:26px 56px}
.tool-group{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:18px 30px}

.tool{gap:8px}
.tool-logo{height:28px}
.tool-label{font-weight:800;font-size:1.15rem;color:var(--body);opacity:.85}

.logo-marquee{overflow:hidden;background:var(--sage);border-radius:var(--r);padding:30px 0}
.logo-track{display:flex;width:max-content;animation:scroll 45s linear infinite}
.logo-marquee:hover .logo-track{animation-play-state:paused}
.tool-set{display:flex;align-items:center;gap:60px;padding-right:60px;flex-shrink:0}
.tool-group{display:flex;flex-wrap:nowrap;align-items:center;gap:60px}
.tool{flex-shrink:0;white-space:nowrap}
@media (prefers-reduced-motion:reduce){.logo-track{animation:none}.logo-marquee{overflow-x:auto}}

.tool-logo{height:auto;max-width:none}

.drives{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}
.drive{display:flex;gap:16px;align-items:flex-start;background:var(--card);border:1.5px solid var(--line);border-radius:var(--r);padding:22px}
.drive h3{margin-bottom:.3em}
.drive p{margin:0;color:var(--muted);font-size:.97rem}
.drive-icon{flex-shrink:0;display:grid;place-items:center;width:46px;height:46px;border-radius:50%;background:var(--sage);border:1.5px solid var(--terra);color:var(--terra-dark)}
@media (max-width:700px){.drives{grid-template-columns:1fr}}

.portrait-title{font-size:.8rem;white-space:nowrap}

/* Warm and polished typography */
body{font-optical-sizing:auto}
h1,h2,h3{font-weight:600;line-height:1.2}
.portrait-cap strong{font-weight:600}

/* A sample output beside the existing workflow description. */
.wf-with-preview{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(230px,1fr);gap:28px;align-items:start}
.wf-description{min-width:0}
.wf-with-preview .wf-grid{column-gap:24px}
.wf-preview{margin:0;min-width:0}
.wf-preview-link{display:block;background:var(--bg);border:1px solid var(--line);border-radius:14px;overflow:hidden;text-decoration:none;box-shadow:var(--shadow);transition:box-shadow .15s}
.wf-preview-link:hover{box-shadow:0 10px 26px rgba(32,52,72,.13)}
.wf-preview img{display:block;width:100%;height:auto;max-height:340px;object-fit:cover;object-position:top}
.wf-preview-action{display:block;padding:11px 14px;border-top:1px solid var(--line);font-size:.82rem;font-weight:600;color:var(--terra-dark);text-align:center}
.wf-preview figcaption{margin-top:8px;font-size:.73rem;line-height:1.5;color:var(--muted);text-align:center}
@media(max-width:860px){.wf-with-preview{grid-template-columns:1fr;gap:24px}.wf-preview{width:100%;max-width:420px;justify-self:center}.wf-preview img{max-height:380px}}

/* Blue tools strip complements the cream page and monochrome portrait. */
.tools,.logo-marquee{background:#E6ECF2}

/* Logo sizes retained from the portfolio. */
.logo-workday{width:93px;height:auto}
.logo-lever{width:86px;height:auto}
.logo-icims{width:92px;height:auto}
.logo-linkedin{width:110px;height:auto}
.logo-phenom{width:95px;height:auto}
.logo-brighthire{width:110px;height:auto}
.logo-claude{width:110px;height:auto}
.logo-gpt{width:34px;height:auto}
.logo-copilot{width:34px;height:auto}
.logo-gemini{width:110px;height:auto}
.logo-github{width:140px;height:auto}

/* Sample previews open in an accessible in-page dialog. */
button.wf-preview-link{width:100%;padding:0;cursor:zoom-in;font:inherit;color:inherit;text-align:inherit}
.sample-dialog{width:min(1000px,96vw);max-width:96vw;max-height:92vh;padding:0;border:1px solid var(--line);border-radius:18px;background:var(--bg);color:var(--ink)}
.sample-dialog::backdrop{background:rgba(21,32,44,.8)}
.sample-dialog-bar{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 20px;background:var(--bg);border-bottom:1px solid var(--line);z-index:1}
.sample-dialog-title{font-family:var(--serif);font-size:1.25rem;margin:0}
.sample-dialog-close{font:inherit;font-size:.9rem;font-weight:600;border:1px solid var(--line);border-radius:999px;padding:8px 14px;background:var(--card);color:var(--ink);cursor:pointer;flex-shrink:0}
.sample-dialog-image{display:block;width:100%;height:auto}
